import {registerCard, register} from "@pihanga2/core";
import {Menu, onMenuClicked} from "@/cards/menu";

register((r) => {
  onMenuClicked(r, (state, {itemID}) => {
    switch (itemID) {
      case "edit":
        state.editMode = true;
        break;
      case "delete":
        state.pendingDelete = state.selectedId;
        break;
    }
  });
});

